using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-reports"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration());
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.GenerateReportAsync();
        }
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using ScenarioRun scenarioRun =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(GreetingResponse_IsCoherentAndRelevant));

        IChatClient chatClient = scenarioRun.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenarioRun.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndFluent()
    {
        await using ScenarioRun scenarioRun =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(FactualQuestion_IsGroundedAndFluent));

        IChatClient chatClient = scenarioRun.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenarioRun.EvaluateAsync(messages);
    }

    private static ChatConfiguration GetChatConfiguration()
    {
        // Configure the chat client for evaluation.
        // In CI, set the AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_MODEL environment variables.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://your-resource.openai.azure.com";
        var model = Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL")
            ?? "gpt-4o-mini";

        IChatClient chatClient =
            new Azure.AI.OpenAI.AzureOpenAIClient(new Uri(endpoint),
                new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(model)
            .AsIChatClient();

        return new ChatConfiguration(chatClient);
    }
}

